const parseCatalogNode = (node) => {
	const catalogNode = getBinaryNodeChild(node, "product_catalog");
	const products = getBinaryNodeChildren(catalogNode, "product").map(parseProductNode);
	const paging = getBinaryNodeChild(catalogNode, "paging");
	return {
		products,
		nextPageCursor: paging ? getBinaryNodeChildString(paging, "after") : void 0
	};
};
const parseCollectionsNode = (node) => {
	return { collections: getBinaryNodeChildren(getBinaryNodeChild(node, "collections"), "collection").map((collectionNode) => {
		return {
			id: getBinaryNodeChildString(collectionNode, "id"),
			name: getBinaryNodeChildString(collectionNode, "name"),
			products: getBinaryNodeChildren(collectionNode, "product").map(parseProductNode),
			status: parseStatusInfo(collectionNode)
		};
	}) };
};
const parseOrderDetailsNode = (node) => {
	const orderNode = getBinaryNodeChild(node, "order");
	const products = getBinaryNodeChildren(orderNode, "product").map((productNode) => {
		const imageNode = getBinaryNodeChild(productNode, "image");
		return {
			id: getBinaryNodeChildString(productNode, "id"),
			name: getBinaryNodeChildString(productNode, "name"),
			imageUrl: getBinaryNodeChildString(imageNode, "url"),
			price: +getBinaryNodeChildString(productNode, "price"),
			currency: getBinaryNodeChildString(productNode, "currency"),
			quantity: +getBinaryNodeChildString(productNode, "quantity")
		};
	});
	const priceNode = getBinaryNodeChild(orderNode, "price");
	return {
		price: {
			total: +getBinaryNodeChildString(priceNode, "total"),
			currency: getBinaryNodeChildString(priceNode, "currency")
		},
		products
	};
};
const toProductNode = (productId, product) => {
	const attrs = {};
	const content = [];
	if (typeof productId !== "undefined") content.push({
		tag: "id",
		attrs: {},
		content: Buffer.from(productId)
	});
	if (typeof product.name !== "undefined") content.push({
		tag: "name",
		attrs: {},
		content: Buffer.from(product.name)
	});
	if (typeof product.description !== "undefined") content.push({
		tag: "description",
		attrs: {},
		content: Buffer.from(product.description)
	});
	if (typeof product.retailerId !== "undefined") content.push({
		tag: "retailer_id",
		attrs: {},
		content: Buffer.from(product.retailerId)
	});
	if (product.images.length) content.push({
		tag: "media",
		attrs: {},
		content: product.images.map((img) => {
			if (!("url" in img)) throw new import_lib.Boom("Expected img for product to already be uploaded", { statusCode: 400 });
			return {
				tag: "image",
				attrs: {},
				content: [{
					tag: "url",
					attrs: {},
					content: Buffer.from(img.url.toString())
				}]
			};
		})
	});
	if (typeof product.price !== "undefined") content.push({
		tag: "price",
		attrs: {},
		content: Buffer.from(product.price.toString())
	});
	if (typeof product.currency !== "undefined") content.push({
		tag: "currency",
		attrs: {},
		content: Buffer.from(product.currency)
	});
	if ("originCountryCode" in product) if (typeof product.originCountryCode === "undefined") attrs["compliance_category"] = "COUNTRY_ORIGIN_EXEMPT";
	else content.push({
		tag: "compliance_info",
		attrs: {},
		content: [{
			tag: "country_code_origin",
			attrs: {},
			content: Buffer.from(product.originCountryCode)
		}]
	});
	if (typeof product.isHidden !== "undefined") attrs["is_hidden"] = product.isHidden.toString();
	return {
		tag: "product",
		attrs,
		content
	};
};
const parseProductNode = (productNode) => {
	const isHidden = productNode.attrs.is_hidden === "true";
	const id = getBinaryNodeChildString(productNode, "id");
	const mediaNode = getBinaryNodeChild(productNode, "media");
	const statusInfoNode = getBinaryNodeChild(productNode, "status_info");
	return {
		id,
		imageUrls: parseImageUrls(mediaNode),
		reviewStatus: { whatsapp: getBinaryNodeChildString(statusInfoNode, "status") },
		availability: "in stock",
		name: getBinaryNodeChildString(productNode, "name"),
		retailerId: getBinaryNodeChildString(productNode, "retailer_id"),
		url: getBinaryNodeChildString(productNode, "url"),
		description: getBinaryNodeChildString(productNode, "description"),
		price: +getBinaryNodeChildString(productNode, "price"),
		currency: getBinaryNodeChildString(productNode, "currency"),
		isHidden
	};
};
/**
* Uploads images not already uploaded to WA's servers
*/
async function uploadingNecessaryImagesOfProduct(product, waUploadToServer, timeoutMs = 3e4) {
	product = {
		...product,
		images: product.images ? await uploadingNecessaryImages(product.images, waUploadToServer, timeoutMs) : product.images
	};
	return product;
}
/**
* Uploads images not already uploaded to WA's servers
*/
const uploadingNecessaryImages = async (images, waUploadToServer, timeoutMs = 3e4) => {
	return await Promise.all(images.map(async (img) => {
		if ("url" in img) {
			const url = img.url.toString();
			if (url.includes(".whatsapp.net")) return { url };
		}
		const { stream } = await getStream(img);
		const hasher = createHash("sha256");
		const filePath = join(tmpdir(), "img" + generateMessageIDV2());
		const encFileWriteStream = createWriteStream(filePath);
		for await (const block of stream) {
			hasher.update(block);
			encFileWriteStream.write(block);
		}
		const { directPath } = await waUploadToServer(filePath, {
			mediaType: "product-catalog-image",
			fileEncSha256B64: hasher.digest("base64"),
			timeoutMs
		});
		await promises.unlink(filePath).catch((err) => console.log("Error deleting temp file ", err));
		return { url: getUrlFromDirectPath(directPath) };
	}));
};
const parseImageUrls = (mediaNode) => {
	const imgNode = getBinaryNodeChild(mediaNode, "image");
	return {
		requested: getBinaryNodeChildString(imgNode, "request_image_url"),
		original: getBinaryNodeChildString(imgNode, "original_image_url")
	};
};
const parseStatusInfo = (mediaNode) => {
	const node = getBinaryNodeChild(mediaNode, "status_info");
	return {
		status: getBinaryNodeChildString(node, "status"),
		canAppeal: getBinaryNodeChildString(node, "can_appeal") === "true"
	};
};
